package local.tvmorph.tv;import android.content.Context;import org.json.*;public class FamilyMemoryCheck{static void check(boolean b){if(!b)throw new AssertionError();}public static void main(String[] args)throws Exception{Context c=new Context();String base=PlaybackMemory.key(PlaybackMemory.account(c,"provider"),"vod","1");check(base.equals("provider:vod:1"));PlaybackMemory.put(c,base,90000,600000);UiSettings.save(c,new JSONObject().put("viewerId","valice"));String alice=PlaybackMemory.key(PlaybackMemory.account(c,"provider"),"vod","1");check(PlaybackMemory.get(c,alice)==0);PlaybackMemory.put(c,alice,45000,600000);UiSettings.save(c,new JSONObject().put("viewerId","vbob"));String bob=PlaybackMemory.key(PlaybackMemory.account(c,"provider"),"vod","1");check(PlaybackMemory.get(c,bob)==0);PlaybackMemory.put(c,bob,60000,600000);UiSettings.save(c,new JSONObject().put("viewerId","valice"));check(PlaybackMemory.get(c,alice)==45000);PlaybackMemory.clear(c);check(PlaybackMemory.get(c,alice)==0&&PlaybackMemory.get(c,bob)==60000&&PlaybackMemory.get(c,base)==90000);UiSettings.save(c,new JSONObject().put("viewerId","default"));check(PlaybackMemory.get(c,base)==90000);PlaybackMemory.clear(c);check(PlaybackMemory.get(c,bob)==60000);System.out.println("PASS: actual playback memory logic isolates viewers; clearing one retains other viewers and legacy default.");}}